// Shared binding and push-constant layout for the VAE decoder shaders.
//
// Every decoder pipeline is built over the *same* four buffers and declares
// the *same* push-constant size, because vk.DispatchMultiTimed records a
// whole graph into one command buffer and requires that. A shader declares
// only the bindings it reads; the descriptors it does not name are inert.
// It is also the right shape for an engine: weights are one arena written
// once, activations are one arena the graph ping-pongs inside, and "which
// tensor" is an offset rather than a descriptor rebind.
//
// The decoder is fp32 except in the mid block, where stage 7 put the four
// projections and the attention on the matrix cores: those read two further
// bindings, an fp16 activation arena and an fp16 weight arena, and the
// shaders that do not use them simply leave them undeclared. Everything else
// is still the fp32 correctness port that had the CPU implementation in
// zimage/vae as its oracle.

layout(binding = 0) readonly buffer Weights { float wbuf[]; };
layout(binding = 1) buffer Act { float act[]; };

layout(push_constant) uniform PC {
    uint inOff;    // element offset of the input tensor in act
    uint outOff;   // element offset of the output tensor in act
    uint C;        // input channels
    uint H;        // input height
    uint W;        // input width
    uint OC;       // output channels
    uint KH;       // kernel height
    uint KW;       // kernel width
    uint pad;      // symmetric zero padding
    uint wOff;     // element offset of the weight tensor in wbuf
    uint bOff;     // element offset of the bias tensor in wbuf, or NO_BIAS
    uint groups;   // group count for group norm
    uint resOff;   // element offset of the residual/second operand in act
    uint aux0;
    uint aux1;
    uint aux2;
    // The GEMM block, mirroring shaders/dit_common.glsl field for field at
    // the same byte offsets. The attention projections run on
    // shaders/dit_gemm.comp *unmodified* -- it is a tuned kernel with three B
    // layouts and a grid swizzle behind it, and porting it onto a second
    // push-constant block would fork it -- so the two blocks have to agree
    // wherever that shader reads: inOff and outOff, which already coincide at
    // 0 and 1, and these six. Their size has to agree too, since
    // vk.DispatchMultiTimed records one push-constant size across a whole
    // command buffer, which is what fixes this block at 22 words.
    uint gemmB;    // B, in the fp16 weight arena
    uint gemmM;    // rows of A and C, padded up to the workgroup tile
    uint gemmN;    // columns of B and C; also C's row stride
    uint gemmK;    // the reduction extent
    uint lda;      // A's row stride in halves
    uint ldb;      // B's row stride in halves; unused when B is tiled
} pc;

const uint NO_BIAS = 0xffffffffu;
===
#version 450
#extension GL_EXT_shader_16bit_storage : require
#extension GL_EXT_shader_explicit_arithmetic_types_float16 : require
// Pack one fp32 [rows, DIM] activation into the fp16 fragment-tile layout
// vae_attention_wmma.comp's cooperative-matrix loads want, adding the
// projection's bias and folding in a scale on the way.
//
// This is shaders/dit_pack_f16.comp's argument on the VAE's binding layout,
// and the argument is IDEAS §5.1b's coverage law applied to a `coopMatLoad`:
// a 16x16 fp16 fragment holds 32 bytes of each of the 16 rows it touches, so
// reading one out of a matrix with any natural row stride puts 16 chunks of
// 32 B, one stride apart, in a single instruction -- an eighth of the bus or
// less. Stored *as fragments*, tile (t, c) -- token rows 16t.., component
// columns 16c.. -- is one contiguous 512 B block and the same load is one
// fully covered read. Stage 3c measured that difference at 1.56x against 30x.
//
// Two modes, built as two pipelines rather than branched at runtime, because
// the two matmuls of attention reduce over different axes and the hardware
// operand layout is K-contiguous for both operands:
//
//   TRANSPOSE 0  stores (row, component) at m*16 + d. That serves q as the A
//     operand of q.k^T, read row-major, *and* k as its B operand, read
//     column-major -- the reduction axis is the component for both.
//   TRANSPOSE 1  stores each tile transposed, at d*16 + m, which serves v as
//     the B operand of p.v, whose reduction axis is the row.
//
// The bias is added here rather than in the GEMM epilogue: the projections
// run on shaders/dit_gemm.comp unmodified, which has no bias, and every one
// of them is read next by either this shader or vae_rows_to_nchw_add.comp.
// So the VAE's four biases live in the two passes that were already reading
// the tensor, and cost nothing.
//
// Rows past pc.aux0 are zeroed rather than skipped: the attention kernel
// reads whole key blocks, so a pad key has to score something finite, and a
// zero key scores zero.
//
// pc.inOff is the fp32 source, pc.outOff the fp16 destination in halves,
// pc.aux0 the real row count, pc.aux1 a scale as a bit pattern and pc.aux2
// the bias in the weight arena, or NO_BIAS.

#include "vae_common.glsl"

layout(binding = 2) writeonly buffer HAct { float16_t hact[]; };

#define TILE 16
#ifndef DIM
#define DIM 512
#endif
#ifndef TRANSPOSE
#define TRANSPOSE 0
#endif
#define DT (DIM / TILE)
#define WG 256

layout(local_size_x = WG) in;

// 16 rows x DIM of the tile this workgroup owns, fp16 so the staging is 16 KB
// rather than 32 at DIM=512. Both sides of the transpose are coalesced
// through it: the read walks whole rows, the write walks whole tiles.
shared float16_t rows[TILE * DIM];

void main() {
    uint tt = gl_WorkGroupID.x;          // row tile
    uint tid = gl_LocalInvocationID.x;
    uint row0 = tt * TILE;
    float scale = uintBitsToFloat(pc.aux1);

    for (uint i = tid; i < TILE * DIM; i += WG) {
        uint m = i / DIM, d = i % DIM;
        uint row = row0 + m;
        float v = 0.0;
        if (row < pc.aux0) {
            v = act[pc.inOff + row * DIM + d];
            if (pc.aux2 != NO_BIAS) {
                v += wbuf[pc.aux2 + d];
            }
            v *= scale;
        }
        rows[i] = float16_t(v);
    }
    barrier();

    uint base = pc.outOff + tt * (DT * TILE * TILE);
    for (uint o = tid; o < DT * TILE * TILE; o += WG) {
        uint c = o / (TILE * TILE);      // component tile
        uint rem = o % (TILE * TILE);
#if TRANSPOSE
        uint m = rem % TILE;
        uint d = c * TILE + rem / TILE;
#else
        uint m = rem / TILE;
        uint d = c * TILE + rem % TILE;
#endif
        hact[base + o] = rows[m * DIM + d];
    }
}
===
#version 450
#extension GL_EXT_shader_16bit_storage : require
#extension GL_EXT_shader_explicit_arithmetic_types_float16 : require
// Narrow an fp32 [rows, C] activation into the fp16 arena as the A operand of
// shaders/dit_gemm.comp: same rows, row stride pc.lda rather than C.
//
// The pad is why the stride is its own field. A fragment load of A issues 16
// addresses one row apart, so an unpadded 512-column row -- 1 KB, a quarter
// of the 4 KB channel rotation -- would put all sixteen in the same DRAM
// channels (§2.3). The pad columns are never read: the reduction stops at
// pc.gemmK.
//
// Rows past pc.aux0 are the GEMM's tile padding. They are written as zeros so
// that whatever the arena held before cannot become an infinity in an operand
// -- the pad rows of C are ignored, but a NaN in A is cheaper to prevent here
// than to explain later.
//
// One workgroup per row, which makes both sides contiguous.

#include "vae_common.glsl"

layout(binding = 2) writeonly buffer HAct { float16_t hact[]; };

#define WG 256
layout(local_size_x = WG) in;

void main() {
    uint r = gl_WorkGroupID.x;
    uint tid = gl_LocalInvocationID.x;
    bool live = r < pc.aux0;
    for (uint c = tid; c < pc.C; c += WG) {
        hact[pc.outOff + r * pc.lda + c] = live
            ? float16_t(act[pc.inOff + r * pc.C + c])
            : float16_t(0.0);
    }
}

