 13	// pushConstants mirrors the PC block in shaders/vae_common.glsl. Every VAE
 14	// pipeline declares the same block, because vk.DispatchMultiTimed records a
 15	// whole graph into one command buffer and requires one push-constant size
 16	// across it.
 17	type pushConstants struct {
 18		InOff, OutOff    uint32
 19		C, H, W          uint32
 20		OC, KH, KW, Pad  uint32
 21		WOff, BOff       uint32
 22		Groups           uint32
 23		ResOff           uint32
 24		Aux0, Aux1, Aux2 uint32
 25		// The GEMM block, at the same byte offsets as zimage/dit's, because the
 26		// mid block's projections run on shaders/dit_gemm.comp unmodified. See
 27		// vae_common.glsl.
 28		GemmB, GemmM, GemmN, GemmK uint32
 29		LDA, LDB                   uint32
 30	}
 31	
 32	const noBias = 0xffffffff
 33	
 34	// dispatchesPerSubmit caps how much work goes into one command buffer. See
 35	// Apply for why it is not simply "all of it", and why 8 is not safe either.
 36	const dispatchesPerSubmit = 4
 37	
 38	func (p pushConstants) bytes() []byte {
 39		out := make([]byte, unsafe.Sizeof(p))
 40		*(*pushConstants)(unsafe.Pointer(&out[0])) = p
 41		return out
 42	}
 43	
 44	// arena hands out element offsets inside one activation buffer. The decoder
 45	// never frees: a decode is a straight line of at most a few dozen live
 46	// tensors, and a bump allocator that a caller resets between runs is both
 47	// simpler and more predictable than reference counting buffers.
 48	type arena struct {
 49		next uint32
 50		high uint32
 51		// free holds released blocks, largest first. A decode is a straight line
 52		// of a few dozen tensors, so a best-fit search over a handful of free
 53		// blocks costs nothing and recovers almost everything a real liveness
 54		// analysis would.
 55		//
 56		// Exact-size bucketing is not enough here, and the reason is the shape
 57		// of this graph: an up block's input is twice the channel count of what
 58		// its resnets produce, so the arena fills with 1.07 GB blocks that can
 59		// never serve the 537 MB requests that follow. That alone was the
 60		// difference between 5.28 GB and the 4.29 GB a single Vulkan storage
 61		// buffer can address on this device.
 62		free []freeBlock
 63	}
 64	
 65	// freeBlock is a released span of the arena.
 66	type freeBlock struct {
 67		off  uint32
 68		size uint32
 69	}
 70	
 71	func roundUp(elems int) uint32 { return uint32((elems + 63) &^ 63) }
 72	
 73	func (a *arena) alloc(elems int) uint32 {
 74		// Keep every tensor 256-byte aligned. IDEAS §5.1b's rule is about row
 75		// strides rather than base addresses, but starting tensors on a channel
 76		// boundary costs nothing and keeps a later fp16 port from inheriting an
 77		// accidental alias.
 78		n := roundUp(elems)
 79		// Best fit: the smallest free block that still holds n. Taking the
 80		// largest instead strands the big blocks the next up-block needs.
 81		best := -1
 82		for i, b := range a.free {
 83			if b.size >= n && (best < 0 || b.size < a.free[best].size) {
 84				best = i
 85			}
 86		}
 87		if best >= 0 {
 88			blk := a.free[best]
 89			a.free = append(a.free[:best], a.free[best+1:]...)
 90			// Return the remainder so a large block is not consumed whole by a
 91			// small request.
 92			if rem := blk.size - n; rem >= 64 {
 93				a.free = append(a.free, freeBlock{off: blk.off + n, size: rem})
 94			}
 95			return blk.off
 96		}
 97		off := a.next
 98		a.next += n
 99		if a.next > a.high {
100			a.high = a.next
101		}
102		return off
103	}
104	
105	// release returns a tensor's block to the free list, coalescing it with any
106	// neighbour so that repeated split/rejoin cycles do not fragment the arena.
107	// Calling it on a tensor that is still read produces silent corruption, so
108	// it is only ever called from the builder, which knows the graph's shape.
109	func (a *arena) release(off uint32, elems int) {
110		blk := freeBlock{off: off, size: roundUp(elems)}
111		for merged := true; merged; {
112			merged = false
113			for i, b := range a.free {
114				if b.off+b.size == blk.off {
115					blk.off, blk.size = b.off, b.size+blk.size
116				} else if blk.off+blk.size == b.off {
117					blk.size += b.size
118				} else {
119					continue
120				}
121				a.free = append(a.free[:i], a.free[i+1:]...)
122				merged = true
123				break
124			}
125		}
126		a.free = append(a.free, blk)
127	}
128	
129	func (a *arena) reset() {
130		a.next = 0
131		a.free = nil
132	}
