148	// GPUDecoder runs the decoder graph on a Vulkan device.
149	type GPUDecoder struct {
150		dev  *vk.Device
151		cpu  *Decoder
152		wbuf *vk.Buffer
153		abuf *vk.Buffer
154		// The fp16 pair, allocated only on the matrix-core path (stage 7): the
155		// activation arena the mid block's operands are packed into, and the four
156		// projection weights in their fragment-tile layout.
157		hbuf   *vk.Buffer
158		w16buf *vk.Buffer
159	
160		pipes map[string]*vk.ComputePipeline
161		mods  []*vk.ShaderModule
162	
163		weights *gpuWeights
164		w16     map[string]uint32
165		arena   arena
166		harena  arena
167	
168		// attn and gemm are the mid block's kernels. A zero attn.spirv means the
169		// fp32 path of stage 2b, which is both the fallback on a device without
170		// matrix cores and the oracle the fp16 path is measured against.
171		attn attnVariant
172		gemm gemmVariant
173	
174		// dispatches accumulates the recorded graph so a decode is one submit.
175		dispatches []vk.MultiDispatch
176	}
