178	// Options selects the mid block's kernels. The zero value is the default
179	// ladder winner on a device that has matrix cores and stage 2b's fp32 path on
180	// one that does not.
181	type Options struct {
182		Attn AttnKernel
183		GEMM GEMMKernel
184	}
