186	// shaderSet is every pipeline the decoder graph uses.
187	var shaderSet = map[string][]byte{
188		"conv2d":     shaders.VAEConv2D,
189		"groupnorm":  shaders.VAEGroupNorm,
190		"silu":       shaders.VAESiLU,
191		"add":        shaders.VAEAdd,
192		"upsample2x": shaders.VAEUpsample2x,
193		"to_rows":    shaders.VAENCHWToRows,
194		"to_nchw":    shaders.VAERowsToNCHWAdd,
195		"linear":     shaders.VAELinear,
196		"attention":  shaders.VAEAttention,
197		"transpose":  shaders.VAETranspose,
198	}
199	
200	// wmmaShaderSet is the rest of the mid block's pipelines, built only when the
201	// device has matrix cores. The attention kernel and the GEMM are not here:
202	// one has a wave size to pin and the other is chosen from a ladder.
203	var wmmaShaderSet = map[string][]byte{
204		"narrow": shaders.VAENarrowF16,
205		"pack":   shaders.VAEPackF16,
206		"packt":  shaders.VAEPackF16T,
207	}
