209	// NewGPUDecoder uploads a loaded decoder's weights and builds its pipelines
210	// with the default kernels. latentH/latentW size the activation arena, which
211	// is allocated once for the largest tensor the graph will hold.
212	func NewGPUDecoder(dev *vk.Device, cpu *Decoder, latentH, latentW int) (*GPUDecoder, error) {
213		return NewGPUDecoderOpts(dev, cpu, latentH, latentW, Options{})
214	}
215	
216	// NewGPUDecoderOpts is NewGPUDecoder with the mid block's kernels named,
217	// which is what the ladder in cmd/vaebench sweeps and what the negative
218	// controls in the tests select.
219	func NewGPUDecoderOpts(dev *vk.Device, cpu *Decoder, latentH, latentW int, opt Options) (*GPUDecoder, error) {
220		g := &GPUDecoder{
221			dev:     dev,
222			cpu:     cpu,
223			pipes:   make(map[string]*vk.ComputePipeline),
224			weights: &gpuWeights{off: make(map[string]uint32)},
225			w16:     make(map[string]uint32),
226		}
227		if err := g.chooseKernels(opt); err != nil {
228			return nil, err
229		}
230	
231		g.flattenWeights()
232	
233		wbytes := len(g.weights.data) * 4
234		var err error
235		if g.wbuf, err = dev.NewBuffer(wbytes); err != nil {
236			g.Destroy()
237			return nil, fmt.Errorf("vae: weight buffer (%d MB): %w", wbytes>>20, err)
238		}
239		g.wbuf.WriteFloat32(g.weights.data)
240	
241		if g.wmma() {
242			w16 := g.stageProjections(cpu.Mid.Attn)
243			if g.w16buf, err = dev.NewBuffer(len(w16) * 2); err != nil {
244				g.Destroy()
245				return nil, fmt.Errorf("vae: fp16 weight buffer (%d MB): %w", (len(w16)*2)>>20, err)
246			}
247			g.w16buf.WriteUint16At(0, w16)
248		}
249	
250		// Measure both arenas by recording the graph once with a throwaway plan.
251		need, hneed, err := g.planSize(latentH, latentW)
252		if err != nil {
253			g.Destroy()
254			return nil, err
255		}
256		if g.abuf, err = dev.NewBuffer(int(need) * 4); err != nil {
257			g.Destroy()
258			return nil, fmt.Errorf("vae: activation buffer (%d MB): %w", (int(need)*4)>>20, err)
259		}
260		// The fp16 arena is allocated even when it is empty, because it is bound
261		// to every pipeline: one descriptor layout across the graph is what lets
262		// vk.DispatchMultiTimed record it into a single command buffer.
263		if g.hbuf, err = dev.NewBuffer(max(int(hneed), 64) * 2); err != nil {
264			g.Destroy()
265			return nil, fmt.Errorf("vae: fp16 activation buffer (%d MB): %w", (int(hneed)*2)>>20, err)
266		}
267		// Zeroed once. Both passes that write it cover their own pad rows, so
268		// this is hygiene rather than an invariant -- but an operand arena that
269		// has never held anything cannot turn a stale bit pattern into an
270		// infinity, and one infinity in a row of A makes that whole row of the
271		// GEMM's output a NaN (stage 6).
272		g.hbuf.WriteFloat32(make([]float32, g.hbuf.Size()/4))
273		if g.w16buf == nil {
274			if g.w16buf, err = dev.NewBuffer(64); err != nil {
275				g.Destroy()
276				return nil, fmt.Errorf("vae: fp16 weight placeholder: %w", err)
277			}
278		}
279	
280		set := map[string][]byte{}
281		for name, spirv := range shaderSet {
282			set[name] = spirv
283		}
284		if g.wmma() {
285			for name, spirv := range wmmaShaderSet {
286				set[name] = spirv
287			}
288		}
289		bufs := []*vk.Buffer{g.wbuf, g.abuf, g.hbuf, g.w16buf}
290		pcSize := uint32(unsafe.Sizeof(pushConstants{}))
291		for name, spirv := range set {
292			if err := g.pipeline(name, spirv, vk.PipelineSpec{Buffers: bufs, PushConstantSize: pcSize}); err != nil {
293				g.Destroy()
294				return nil, err
295			}
296		}
297		if g.wmma() {
298			// Both matrix-core kernels map gl_SubgroupID onto a wave grid, so
299			// their wave size is pinned rather than assumed: at the wrong size a
300			// workgroup holds the wrong number of waves and half of them write
301			// outside the tile.
302			if err := g.pipeline("attn_wmma", g.attn.spirv, vk.PipelineSpec{
303				Buffers: bufs, PushConstantSize: pcSize, RequiredSubgroupSize: g.attn.wave,
304			}); err != nil {
305				g.Destroy()
306				return nil, err
307			}
308			spec := vk.PipelineSpec{Buffers: bufs, PushConstantSize: pcSize}
309			if g.gemm.waves > 1 {
310				spec.RequiredSubgroupSize = 64
311			}
312			if err := g.pipeline("gemm", g.gemm.spirv, spec); err != nil {
313				g.Destroy()
314				return nil, err
315			}
316		}
317		return g, nil
318	}
