320	// chooseKernels resolves Options against what the device can actually do.
321	func (g *GPUDecoder) chooseKernels(opt Options) error {
322		if opt.Attn == AttnScalar {
323			return nil
324		}
325		if !hasMatrixCores(g.dev) {
326			if opt.Attn != "" {
327				return fmt.Errorf("vae: attention kernel %q needs fp16, cooperative matrices and subgroup size control", opt.Attn)
328			}
329			return nil
330		}
331		attn := opt.Attn
332		if attn == "" {
333			attn = DefaultAttnKernel
334		}
335		v, ok := attnVariantFor(attn)
336		if !ok {
337			return fmt.Errorf("vae: no attention kernel %q (have %v)", attn, AttnKernels())
338		}
339		gk := opt.GEMM
340		if gk == "" {
341			gk = DefaultGEMMKernel
342		}
343		gv, ok := gemmVariantFor(gk)
344		if !ok {
345			return fmt.Errorf("vae: no GEMM kernel %q (have %v)", gk, GEMMKernels())
346		}
347		g.attn, g.gemm = v, gv
348		return nil
349	}
