362	// pipeline builds one pipeline and records its module for destruction.
363	func (g *GPUDecoder) pipeline(name string, spirv []byte, spec vk.PipelineSpec) error {
364		mod, err := g.dev.NewShaderModule(spirv)
365		if err != nil {
366			return fmt.Errorf("vae: shader %s: %w", name, err)
367		}
368		g.mods = append(g.mods, mod)
369		pipe, err := g.dev.NewPipeline(mod, spec)
370		if err != nil {
371			return fmt.Errorf("vae: pipeline %s: %w", name, err)
372		}
373		g.pipes[name] = pipe
374		return nil
375	}
