377	// Destroy releases every Vulkan object.
378	func (g *GPUDecoder) Destroy() {
379		for _, p := range g.pipes {
380			p.Destroy()
381		}
382		for _, m := range g.mods {
383			m.Destroy()
384		}
385		if g.abuf != nil {
386			g.abuf.Destroy()
387		}
388		if g.wbuf != nil {
389			g.wbuf.Destroy()
390		}
391		if g.hbuf != nil {
392			g.hbuf.Destroy()
393		}
394		if g.w16buf != nil {
395			g.w16buf.Destroy()
396		}
397	}
