399	// flattenWeights copies every weight the graph reads into one arena, in the
400	// order the graph reads them.
401	func (g *GPUDecoder) flattenWeights() {
402		w := g.weights
403		conv := func(name string, c *Conv2D) {
404			w.put(name+".weight", c.Weight)
405			if c.Bias != nil {
406				w.put(name+".bias", c.Bias)
407			}
408		}
409		norm := func(name string, n *GroupNorm) {
410			w.put(name+".weight", n.Weight)
411			w.put(name+".bias", n.Bias)
412		}
413		lin := func(name string, l *Linear) {
414			w.put(name+".weight", l.Weight)
415			if l.Bias != nil {
416				w.put(name+".bias", l.Bias)
417			}
418		}
419		resnet := func(name string, r *ResnetBlock) {
420			norm(name+".norm1", r.Norm1)
421			conv(name+".conv1", r.Conv1)
422			norm(name+".norm2", r.Norm2)
423			conv(name+".conv2", r.Conv2)
424			if r.Shortcut != nil {
425				conv(name+".shortcut", r.Shortcut)
426			}
427		}
428	
429		conv("conv_in", g.cpu.ConvIn)
430		resnet("mid.r1", g.cpu.Mid.Resnet1)
431		norm("mid.attn.norm", g.cpu.Mid.Attn.GroupNorm)
432		lin("mid.attn.q", g.cpu.Mid.Attn.Q)
433		lin("mid.attn.k", g.cpu.Mid.Attn.K)
434		lin("mid.attn.v", g.cpu.Mid.Attn.V)
435		lin("mid.attn.out", g.cpu.Mid.Attn.Out)
436		resnet("mid.r2", g.cpu.Mid.Resnet2)
437		for i, up := range g.cpu.UpBlocks {
438			for j, r := range up.Resnets {
439				resnet(fmt.Sprintf("up.%d.r%d", i, j), r)
440			}
441			if up.Upsampler != nil {
442				conv(fmt.Sprintf("up.%d.upconv", i), up.Upsampler)
443			}
444		}
445		norm("conv_norm_out", g.cpu.ConvNormOut)
446		conv("conv_out", g.cpu.ConvOut)
447	}
448	
449	// tensor is a shape plus its offset in the activation arena.
450	type tensor struct {
451		off     uint32
452		C, H, W int
453	}
454	
455	func (t tensor) elems() int { return t.C * t.H * t.W }
456	
457	// builder records the decode graph into a dispatch list.
458	type builder struct {
459		g     *GPUDecoder
460		ar    *arena
461		har   *arena
462		out   []vk.MultiDispatch
463		kinds []string
464		flops []float64
465	
466		pendingKind  string
467		pendingFlops float64
468	
469		err error
470	}
471	
472	// label names the next dispatch for the profiler and records its arithmetic.
473	func (b *builder) label(kind string, flops float64) {
474		b.pendingKind, b.pendingFlops = kind, flops
475	}
476	
477	func groups(n, local int) uint32 { return uint32((n + local - 1) / local) }
478	
479	func (b *builder) add(pipe string, gx uint32, pc pushConstants) {
480		b.addXY(pipe, gx, 1, pc)
481	}
482	
483	// addXY records a dispatch with a two-dimensional grid. The convolution uses
484	// it: x covers spatial tiles and y covers output channels, so one workgroup
485	// owns one channel's filter and can stage it through shared memory.
486	func (b *builder) addXY(pipe string, gx, gy uint32, pc pushConstants) {
487		if b.err != nil {
488			return
489		}
490		// planSize records the same graph with no pipelines built, purely to
491		// size the arena, so a missing pipeline is an error only once there are
492		// any at all.
493		p := b.g.pipes[pipe]
494		if p == nil && len(b.g.pipes) > 0 {
495			b.err = fmt.Errorf("vae: no pipeline %q", pipe)
496			return
497		}
498		b.out = append(b.out, vk.MultiDispatch{Pipeline: p, GroupsX: gx, GroupsY: gy, PushConstants: pc.bytes()})
499		kind := b.pendingKind
500		if kind == "" {
501			kind = pipe
502		}
503		b.kinds = append(b.kinds, kind)
504		b.flops = append(b.flops, b.pendingFlops)
505		b.pendingKind, b.pendingFlops = "", 0
506	}
507	
508	// release marks tensors dead so their memory can back later ones.
509	func (b *builder) release(ts ...tensor) {
510		for _, t := range ts {
511			b.ar.release(t.off, t.elems())
512		}
513	}
514	
515	func (b *builder) wOff(name string) uint32 {
516		off, ok := b.g.weights.off[name]
517		if !ok && b.err == nil {
518			b.err = fmt.Errorf("vae: no weight %q", name)
519		}
520		return off
521	}
522	
523	func (b *builder) bOff(name string) uint32 {
524		if off, ok := b.g.weights.off[name]; ok {
525			return off
526		}
527		return noBias
528	}
529	
530	// conv appends a convolution producing a fresh tensor.
531	func (b *builder) conv(name string, c *Conv2D, x tensor) tensor {
532		out := tensor{off: b.ar.alloc(c.OutC * x.H * x.W), C: c.OutC, H: x.H, W: x.W}
533		if c.Pad == 0 && c.KH == 1 {
534			// 1x1 with no padding also preserves H and W.
535			out.H, out.W = x.H, x.W
536		}
537		b.label(fmt.Sprintf("conv%dx%d %d->%d @%dx%d", c.KH, c.KW, x.C, c.OutC, x.H, x.W),
538			2*float64(c.OutC)*float64(out.H)*float64(out.W)*float64(x.C)*float64(c.KH)*float64(c.KW))
539		// The grid's y axis is output-channel *blocks*: the shader's OC_BLOCK
540		// accumulators per thread are what give the kernel its arithmetic
541		// intensity, so the channel count is divided by that here.
542		const convOCBlock = 8
543		b.addXY("conv2d", groups(out.H*out.W, 256), groups(c.OutC, convOCBlock), pushConstants{
544			InOff: x.off, OutOff: out.off,
545			C: uint32(x.C), H: uint32(x.H), W: uint32(x.W),
546			OC: uint32(c.OutC), KH: uint32(c.KH), KW: uint32(c.KW), Pad: uint32(c.Pad),
547			WOff: b.wOff(name + ".weight"), BOff: b.bOff(name + ".bias"),
548		})
549		return out
550	}
551	
552	// norm appends a group norm in place.
553	func (b *builder) norm(name string, n *GroupNorm, x tensor) tensor {
554		b.add("groupnorm", uint32(n.Groups), pushConstants{
555			InOff: x.off, OutOff: x.off,
556			C: uint32(x.C), H: uint32(x.H), W: uint32(x.W),
557			WOff: b.wOff(name + ".weight"), BOff: b.wOff(name + ".bias"),
558			Groups: uint32(n.Groups),
559			Aux0:   math.Float32bits(float32(n.Eps)),
560		})
561		return x
562	}
563	
564	// silu appends an in-place SiLU.
565	func (b *builder) silu(x tensor) tensor {
566		b.add("silu", groups(x.elems(), 256), pushConstants{
567			InOff: x.off, OutOff: x.off, Aux0: uint32(x.elems()),
568		})
569		return x
570	}
571	
572	// addInto appends out = a + res, writing into a.
573	func (b *builder) addInto(a, res tensor) tensor {
574		b.add("add", groups(a.elems(), 256), pushConstants{
575			InOff: a.off, OutOff: a.off, ResOff: res.off, Aux0: uint32(a.elems()),
576		})
577		return a
578	}
579	
580	func (b *builder) resnet(name string, r *ResnetBlock, x tensor) tensor {
581		// norm1 writes into a fresh tensor rather than over x, because x is the
582		// residual and is read again at the end of the block.
583		//
584		// Every release below happens *after* the dispatch that consumes the
585		// tensor has been recorded, and after the next tensor has been
586		// allocated. Releasing earlier would let the allocator hand the same
587		// block to a tensor that is still being read from it.
588		h := tensor{off: b.ar.alloc(x.elems()), C: x.C, H: x.H, W: x.W}
589		b.add("groupnorm", uint32(r.Norm1.Groups), pushConstants{
590			InOff: x.off, OutOff: h.off,
591			C: uint32(x.C), H: uint32(x.H), W: uint32(x.W),
592			WOff: b.wOff(name + ".norm1.weight"), BOff: b.wOff(name + ".norm1.bias"),
593			Groups: uint32(r.Norm1.Groups), Aux0: math.Float32bits(float32(r.Norm1.Eps)),
594		})
595		h = b.silu(h)
596	
597		h1 := b.conv(name+".conv1", r.Conv1, h)
598		b.release(h)
599		h1 = b.norm(name+".norm2", r.Norm2, h1)
600		h1 = b.silu(h1)
601	
602		h2 := b.conv(name+".conv2", r.Conv2, h1)
603		b.release(h1)
604	
605		skip := x
606		if r.Shortcut != nil {
607			skip = b.conv(name+".shortcut", r.Shortcut, x)
608		}
609		out := b.addInto(h2, skip)
610		if r.Shortcut != nil {
611			b.release(skip)
612		}
613		b.release(x)
614		return out
615	}
616	
617	func (b *builder) attention(name string, a *Attention, x tensor) tensor {
618		rows := x.H * x.W
619		dim := a.Q.Out
620	
621		h := tensor{off: b.ar.alloc(x.elems()), C: x.C, H: x.H, W: x.W}
622		b.add("groupnorm", uint32(a.GroupNorm.Groups), pushConstants{
623			InOff: x.off, OutOff: h.off,
624			C: uint32(x.C), H: uint32(x.H), W: uint32(x.W),
625			WOff: b.wOff(name + ".norm.weight"), BOff: b.wOff(name + ".norm.bias"),
626			Groups: uint32(a.GroupNorm.Groups), Aux0: math.Float32bits(float32(a.GroupNorm.Eps)),
627		})
628	
629		seq := tensor{off: b.ar.alloc(rows * x.C), C: x.C, H: x.H, W: x.W}
630		b.add("to_rows", groups(rows*x.C, 256), pushConstants{
631			InOff: h.off, OutOff: seq.off,
632			C: uint32(x.C), H: uint32(x.H), W: uint32(x.W),
633		})
634	
635		proj := func(pname string, l *Linear) tensor {
636			out := tensor{off: b.ar.alloc(rows * l.Out), C: l.Out, H: x.H, W: x.W}
637			b.label(fmt.Sprintf("linear %d->%d x%d", l.In, l.Out, rows),
638				2*float64(rows)*float64(l.Out)*float64(l.In))
639			b.add("linear", groups(rows*l.Out, 64), pushConstants{
640				InOff: seq.off, OutOff: out.off,
641				C: uint32(l.In), H: uint32(x.H), W: uint32(x.W), OC: uint32(l.Out),
642				WOff: b.wOff(pname + ".weight"), BOff: b.bOff(pname + ".bias"),
643			})
644			return out
645		}
646		q := proj(name+".q", a.Q)
647		k := proj(name+".k", a.K)
648		v := proj(name+".v", a.V)
649	
650		// Transpose K so the score loop reads consecutive keys at consecutive
651		// addresses (IDEAS §5.1b). The +64 pads the destination row stride off a
652		// multiple of the 4 KB channel rotation, which is what puts the gcd
653		// inside §5.1b's [128, 256] byte window.
654		kStride := rows + 64
655		kT := tensor{off: b.ar.alloc(dim * kStride), C: dim, H: 1, W: kStride}
656		b.label(fmt.Sprintf("transpose %dx%d", rows, dim), 0)
657		b.add("transpose", groups(rows*dim, 256), pushConstants{
658			InOff: k.off, OutOff: kT.off,
659			C: uint32(dim), Aux0: uint32(rows), Aux1: uint32(kStride),
660		})
661	
662		ctx := tensor{off: b.ar.alloc(rows * dim), C: dim, H: x.H, W: x.W}
663		// Two passes of q.k plus the weighted sum of v, all over rows x rows.
664		b.label(fmt.Sprintf("attention %d rows x %d", rows, dim),
665			3*2*float64(rows)*float64(rows)*float64(dim))
666		b.add("attention", uint32(rows), pushConstants{
667			InOff: q.off, OutOff: ctx.off, ResOff: kT.off,
668			C:      uint32(dim),
669			Groups: uint32(kStride),
670			Aux0:   uint32(rows), Aux1: math.Float32bits(float32(a.Scale)), Aux2: v.off,
671		})
672	
673		outRows := tensor{off: b.ar.alloc(rows * a.Out.Out), C: a.Out.Out, H: x.H, W: x.W}
674		b.label(fmt.Sprintf("linear %d->%d x%d", a.Out.In, a.Out.Out, rows),
675			2*float64(rows)*float64(a.Out.Out)*float64(a.Out.In))
676		b.add("linear", groups(rows*a.Out.Out, 64), pushConstants{
677			InOff: ctx.off, OutOff: outRows.off,
678			C: uint32(a.Out.In), H: uint32(x.H), W: uint32(x.W), OC: uint32(a.Out.Out),
679			WOff: b.wOff(name + ".out.weight"), BOff: b.bOff(name + ".out.bias"),
680		})
681	
682		res := tensor{off: b.ar.alloc(x.elems()), C: x.C, H: x.H, W: x.W}
683		// The bias is in the projection above on this path, so the fused add has
684		// none of its own -- there is no push-constant value that means "not set"
685		// (stage 6), so it is said explicitly.
686		b.add("to_nchw", groups(x.elems(), 256), pushConstants{
687			InOff: outRows.off, OutOff: res.off, ResOff: x.off,
688			C: uint32(x.C), H: uint32(x.H), W: uint32(x.W),
689			Aux0: noBias,
690		})
691		b.release(h, seq, q, k, kT, v, ctx, outRows, x)
692		return res
693	}
694	
695	func (b *builder) upsample(name string, c *Conv2D, x tensor) tensor {
696		up := tensor{off: b.ar.alloc(x.C * x.H * 2 * x.W * 2), C: x.C, H: x.H * 2, W: x.W * 2}
697		b.add("upsample2x", groups(up.elems(), 256), pushConstants{
698			InOff: x.off, OutOff: up.off,
699			C: uint32(x.C), H: uint32(x.H), W: uint32(x.W),
700		})
701		b.release(x)
702		out := b.conv(name, c, up)
703		b.release(up)
704		return out
705	}
706	
707	// build records the whole decode and returns the output tensor.
708	func (b *builder) build(latentH, latentW int) tensor {
709		d := b.g.cpu
710		x := tensor{off: b.ar.alloc(d.ConvIn.InC * latentH * latentW), C: d.ConvIn.InC, H: latentH, W: latentW}
711		h := b.conv("conv_in", d.ConvIn, x)
712		h = b.resnet("mid.r1", d.Mid.Resnet1, h)
713		if b.g.wmma() {
714			h = b.attentionWMMA("mid.attn", d.Mid.Attn, h)
715		} else {
716			h = b.attention("mid.attn", d.Mid.Attn, h)
717		}
718		h = b.resnet("mid.r2", d.Mid.Resnet2, h)
719		for i, up := range d.UpBlocks {
720			for j, r := range up.Resnets {
721				h = b.resnet(fmt.Sprintf("up.%d.r%d", i, j), r, h)
722			}
723			if up.Upsampler != nil {
724				h = b.upsample(fmt.Sprintf("up.%d.upconv", i), up.Upsampler, h)
725			}
726		}
727		h = b.norm("conv_norm_out", d.ConvNormOut, h)
728		h = b.silu(h)
729		out := b.conv("conv_out", d.ConvOut, h)
730		b.release(h)
731		return out
732	}
733	
734	// planSize records the graph with no pipelines bound, purely to find how
735	// large each of the two activation arenas has to be.
736	func (g *GPUDecoder) planSize(latentH, latentW int) (uint32, uint32, error) {
737		saved := g.pipes
738		g.pipes = map[string]*vk.ComputePipeline{}
739		b := &builder{g: g, ar: &arena{}, har: &arena{}}
740		b.build(latentH, latentW)
741		g.pipes = saved
742		if b.err != nil {
743			return 0, 0, b.err
744		}
745		return b.ar.high, b.har.high, nil
746	}
747	
748	// Apply decodes a latent on the GPU. The whole graph -- 100-odd dispatches
749	// -- is recorded into one command buffer and submitted once, with a barrier
750	// between every pair, because each stage reads what the previous wrote.
751	func (g *GPUDecoder) Apply(latent *Tensor) (*Tensor, error) {
752		if latent.N != 1 {
753			return nil, fmt.Errorf("vae: GPU decoder handles one image at a time, got N=%d", latent.N)
754		}
755		if latent.C != g.cpu.ConvIn.InC {
756			return nil, fmt.Errorf("vae: latent has %d channels, conv_in takes %d", latent.C, g.cpu.ConvIn.InC)
757		}
758	
759		g.arena.reset()
760		g.harena.reset()
761		b := &builder{g: g, ar: &g.arena, har: &g.harena}
762		out := b.build(latent.H, latent.W)
763		if b.err != nil {
764			return nil, b.err
765		}
766		if int(b.har.high)*2 > g.hbuf.Size() {
767			return nil, fmt.Errorf("vae: graph needs %d MB of fp16 activations, arena is %d MB",
768				(int(b.har.high)*2)>>20, g.hbuf.Size()>>20)
769		}
