	skip := x
	if r.Shortcut != nil {
		skip = b.conv(name+".shortcut", r.Shortcut, x)
	}
	out := b.addInto(h2, skip)
	if r.Shortcut != nil {
		b.release(skip)
	}
	b.release(x)
	return out
}

func (b *builder) attention(name string, a *Attention, x tensor) tensor {
