package main

import (
	"flag"
	"fmt"
	"log"
	"time"

	"strix-halo-vulkan/vk"
)

func main() {
	buffer := flag.Int("buffer", 63, "buffer size in MB")
	chunk := flag.Int("chunk", 63, "bytes moved per measurement, in MB")
	flag.Parse()
	inst, err := vk.NewInstance("bus")
	if err != nil {
		log.Fatal(err)
	}
	defer inst.Destroy()
	devs, _ := inst.PhysicalDevices()
	phys := &devs[0]
	for i := range devs {
		if devs[i].DeviceID == 0x1586 {
			phys = &devs[i]
		}
	}
	qf, _ := phys.ComputeQueueFamily()
	dev, err := vk.NewDevice(phys, qf, vk.DeviceFeatures{})
	if err != nil {
		log.Fatal(err)
	}
	defer dev.Destroy()

	buf, err := dev.NewBuffer(*buffer << 20)
	if err != nil {
		log.Fatal(err)
	}
	defer buf.Destroy()
	n := (*chunk << 20) / 4
	src := make([]float32, n)
	for i := range src {
		src[i] = float32(i % 97)
	}
	for rep := 0; rep < 3; rep++ {
		t0 := time.Now()
		buf.WriteFloat32At(0, src)
		w := time.Since(t0)
		t0 = time.Now()
		out := buf.ReadFloat32At(0, n)
		r := time.Since(t0)
		mb := float64(n*4) / 1e6
		fmt.Printf("buffer %5d MB  move %.0f MB  write %9s (%5.1f GB/s)  read %9s (%5.2f GB/s)  sum %g\n",
			*buffer, mb, w.Round(time.Microsecond), mb/1e3/w.Seconds(),
			r.Round(time.Microsecond), mb/1e3/r.Seconds(), out[n-1])
	}
}
